template:
fn apply_twice<F: ⟦bound⟧>(
    val: i32,
    f: F,
) -> i32 {
    let _ = f(val);
    f(val)
}

fn main() {
    let mut factor = 3;
    let tag = String::from("multiply");
    let calc = ⟦closure_expr⟧;
    let res = apply_twice(5, calc);
    assert_eq!(res, 15);
}

tests:
#[test]
fn applies_twice() {
    let factor = 3;
    let calc = |x: i32| x * factor;
    assert_eq!(apply_twice(5, calc), 15);
}
